/// <summary>
/// Gets the number sequence for the Nat30 Number for Nat3040.
/// </summary>
/// <returns>
/// Number sequence got.
/// </returns>
public static NumberSequenceReference numRefNat30Number()
{
    NumberSeqScope scope = NumberSeqScopeFactory::createDataAreaScope(curext());
    return NumberSeqReference::findReference(extendedTypeNum(METNat30Number), scope);
}

/// <summary>
/// Gets the number sequence for the vendLegalEntityId.
/// MPJ_21178_VendorGlobal by chaminda on 07 Mar 2022
/// </summary>
/// <returns>
/// Number sequence got.
/// </returns>
public static NumberSequenceReference numRefVendLegalEntityId()
{
    NumberSeqScope scope = NumberSeqScopeFactory::createGlobalScope();
    return NumberSeqReference::findReference(extendedTypeNum(MetVendLegalEntityID),scope);
}

